function architectureBodyHeight(id,h){return architectureProfiles[id]?.roof==='tapered'?h*.52:h}
function architectureDetails(features,heights){const output=[];
const point=(p,dx,dy)=>[p[0]+dx/72400,p[1]+dy/111320];
function polygon(coords,base,height,color,id){if(height<=base)return;output.push({type:'Feature',properties:{id,base,height,color},geometry:{type:'Polygon',coordinates:[closeRing(coords)]}})}
function strip(a,b,start,end,width){const dx=(b[0]-a[0])*72400,dy=(b[1]-a[1])*111320,len=Math.hypot(dx,dy);const ux=dx/len,uy=dy/len,nx=-uy*width,ny=ux*width;const p=point(a,ux*start,uy*start),q=point(a,ux*end,uy*end);return [point(p,nx,ny),point(q,nx,ny),point(q,-nx,-ny),point(p,-nx,-ny)]}
for(const f of features.filter(f=>architectureProfiles[f.id])){const p=architectureProfiles[f.id],h=heights[f.id]?.height||12,body=architectureBodyHeight(f.id,h),rows=p.rows,step=body/rows,ring=f.points;for(let e=0;e<ring.length-1;e++){const a=ring[e],b=ring[e+1],length=Math.hypot((b[0]-a[0])*72400,(b[1]-a[1])*111320);if(length<1)continue;const count=Math.max(1,Math.floor(length/p.spacing));for(let level=0;level<rows;level++){const base=level*step+step*.2,top=base+step*p.band;for(let k=0;k<count;k++){const start=k*length/count+.22,end=(k+1)*length/count-.22;if(end<=start)continue;polygon(strip(a,b,start,end,.13),base,Math.min(top,body-.2),p.glass,f.id)}polygon(strip(a,b,0,length,.24),Math.max(.1,(level+1)*step-.28),Math.min((level+1)*step,body),p.trim,f.id)}polygon(strip(a,b,0,length,.32),body,body+.25,p.trim,f.id)}
if(p.roof==='tapered'){const center=centerOf(ring);for(let r=0;r<12;r++){const scale=1-r*.028;const coords=ring.map(v=>[center[0]+(v[0]-center[0])*scale,center[1]+(v[1]-center[1])*scale]);polygon(coords,body+(h-body)*r/12,body+(h-body)*(r+1)/12,p.wall,f.id)}}
if(p.roof==='plant'){const center=centerOf(ring);for(const scale of [.68,.40]){const coords=ring.map(v=>[center[0]+(v[0]-center[0])*scale,center[1]+(v[1]-center[1])*scale]);polygon(coords,h,h+(scale===.68?1.4:2.3),'#bbbdb6',f.id)}}
}return output}
